                    "#sourceCode": [
                      "vrmlscript:\r",
                      " function addEvents(value, time) { events_added = value; }\r",
                      " function addAvatars(value, time) { avatars_added = value; }\r",
                      " function addObjects(value, time)\r",
                      " {\r",
                      "  j = objects.length;\r",
                      "  for ( i = 0 ; i < value.length ; i++ )\r",
                      "  {\r",
                      "   objects[j++] = value[i]; \r",
                      "  }\r",
                      "  objects_added = value;\r",
                      " }\r",
                      " function removeEvents(value, time) { events_removed = value; }\r",
                      " function removeAvatars(value, time) { avatars_removed = value; }\r",
                      " function removeObjects(value, time)\r",
                      " {\r",
                      "  for ( i = 0 ; i < value.length ; i++ )\r",
                      "  {\r",
                      "   for ( j = 0 ; j < objects.length ; j++ )\r",
                      "   {\r",
                      "    if ( objects[j] == value[i] )\r",
                      "    {\r",
                      "     //objects[j] = NULL;\r",
                      "     break;\r",
                      "    }\r",
                      "   }\r",
                      "  }\r",
                      "  objects_removed = value;\r",
                      " }\r",
                      " function set_action( value, time )\r",
                      " {\r",
                      "   if ( value.length <= 9 )\r",
                      "   {\r",
                      "     Browser.print('wrong action '+value);\r",
                      "     return;\r",
                      "   }\r",
                      "   oid = value.substring( 0, 9 );\r",
                      "   action = value.substring( 9, value.length );\r",
                      "   intid = parseInt( oid.substring( 1, oid.length ), 16 );\r",
                      "   for ( j = 0 ; j < objects.length ; j++ )\r",
                      "   {\r",
                      "    // Old Contacts sets the id in decimal instead of hex so we have to convert it\r",
                      "    if( parseFloat( Browser.version ) < 5.020 )\r",
                      "      id = parseInt( objects[j].id.substring( 1, objects[j].id.length ), 10 );\r",
                      "    else\r",
                      "      id = parseInt( objects[j].id.substring( 1, objects[j].id.length ), 16 );\r",
                      "    if ( id == intid )\r",
                      "    {\r",
                      "     // call action in the inlined object. it must contain a set_action field \r",
                      "     // in the first node.\r",
                      "     objects[j].children[0].children[0].level[0].children[0].set_action = action;\r",
                      "     break;\r",
                      "    }\r",
                      "   }\r",
                      " }\r",
                      " function set_myAvatarGesture(value, time) { myAvatarGestureToServer = value; }\r",
                      " function myAvatarGestureFromServer(value, time) { myAvatarGesture_changed = value; }\r",
                      " function set_myAvatarURL(value, time) { myAvatarURL_changed = value; }\r",
                      " function initialize()\r",
                      " {\r",
                      "  dropPosition = pos[0]+','+pos[1]+','+pos[2]+',0,'+rot[1]+',0,'+rot[3];\r",
                      " }\r",
                      " function beamto(v, t)\r",
                      " {\r",
                      " i = 0;\r",
                      " j = 0;\r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " {\r",
                      "   pos[0] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " }\r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " {\r",
                      "   pos[1] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " } \r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " {\r",
                      "   pos[2] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " } \r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " { \r",
                      "   rot[0] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " } \r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " { \r",
                      "   rot[1] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " } \r",
                      " if ( (j = v.indexOf(',', i)) >= 0 ) \r",
                      " { \r",
                      "   rot[2] = parseFloat(v.substring( i, j ));\r",
                      "   j += 1; i = j;\r",
                      " } \r",
                      " j = v.length; \r",
                      " rot[3] = parseFloat(v.substring( i, j ));\r",
                      " if (rot[1] > 0)\r",
                      "   pos[0] = pos[0] + (beamtodistance * Math.sin(rot[3]));\r",
                      " else\r",
                      "   pos[0] = pos[0] - (beamtodistance * Math.sin(rot[3]));\r",
                      " pos[2] = pos[2] + (beamtodistance * Math.cos(rot[3]));\r",
                      " rot[0] = rot[2] = 0;\r",
                      " if ( rot[1] < 0 ) rot[1] = -1;\r",
                      " else rot[1] = 1;\r",
                      " Browser.setViewpointByValue(pos, rot, 0);\r",
                      " }\r",
                      " function calcDropPosition(v, t)\r",
                      " {\r",
                      " Browser.getViewpointByValue(pos, rot, 1);\r",
                      " if (rot[1] > 0)\r",
                      "   pos[0] = pos[0] - (beamtodistance * Math.sin(rot[3]));\r",
                      " else\r",
                      "   pos[0] = pos[0] + (beamtodistance * Math.sin(rot[3]));\r",
                      " pos[2] = pos[2] - (beamtodistance * Math.cos(rot[3]));\r",
                      " if ( rot[1] < 0 ) rot[1] = -1; \r",
                      " else rot[1] = 1;\r",
                      " dropPosition = pos[0]+','+pos[1]+','+pos[2]+',0,'+rot[1]+',0,'+rot[3];\r",
                      " }\r",
                      " function loadScene( value, time )\r",
                      " {\r",
                      "   Browser.loadURL( value, 'target=Chat' );\r",
                      " }\r",
                      ""
                    ],
