        { "ProtoDeclare":
          {
            "@name": "Actlog3DArea",
            "ProtoInterface": {
              "field": [
                {
                  "@accessType": "inputOutput",
                  "@type": "SFVec3f",
                  "@name": "center"
                },
                {
