                  "@value": 1
                }
              ]
            },
            "ProtoBody": {
              "-children": [
                { "ProximitySensor":
                  {
                    "@DEF": "PS",
                    "IS": {
                      "connect": [
                        {
                          "@nodeField": "size",
                          "@protoField": "size"
                        },
                        {
                          "@nodeField": "center",
                          "@protoField": "center"
                        }
                      ]
                    }
                  }
                },
                { "Script":
                  {
                    "@DEF": "S",
                    "field": [
                      {
                        "@accessType": "inputOutput",
                        "@type": "SFString",
                        "@name": "id"
                      },
                      {
                        "@accessType": "inputOutput",
                        "@type": "SFFloat",
                        "@name": "fieldOfView"
                      },
                      {
                        "@accessType": "inputOutput",
                        "@type": "SFRotation",
                        "@name": "orientation"
                      },
                      {
                        "@accessType": "inputOutput",
                        "@type": "SFInt32",
                        "@name": "count"
                      },
                      {
                        "@accessType": "inputOnly",
                        "@type": "SFTime",
                        "@name": "enter"
                      },
                      {
                        "@accessType": "inputOnly",
                        "@type": "SFRotation",
                        "@name": "curOrientation"
                      },
                      {
                        "@accessType": "outputOnly",
                        "@type": "SFBool",
                        "@name": "disable"
                      }
                    ],
                    "#sourceCode": [
                      "vrmlscript:\r",
                      "function load()\r",
                      "{\r",
                      "  if( !count )\r",
                      "    return;\r",
                      "  if( count > 0 )\r",
                      "  count--;\r",
                      "  if( count == 0 )\r",
                      "    disable = FALSE;\r",
                      "  Browser.loadURL( 'javascript:log3DArea(\\''+id+'\\')', 'target=action' );\r",
                      "}\r",
                      "function curOrientation( v, t )\r",
                      "{\r",
                      "  if( !orientation[1] )\r",
                      "    return;\r",
                      "  if( v[1] < 0 )\r",
                      "  {\r",
                      "    v[3] = -1 * v[3];\r",
                      "  }\r",
                      "  if( v[3] < 0 )\r",
                      "  {\r",
                      "    v[3] += 2*Math.PI;\r",
                      "  }\r",
                      "  if( v[3]+fieldOfView > orientation[3] && v[3]-fieldOfView < orientation[3] )\r",
                      "  {\r",
                      "    load();\r",
                      "  }\r",
                      "}\r",
                      "function enter()\r",
                      "{\r",
                      "  if( !orientation[1] )\r",
                      "  {\r",
                      "    load();\r",
                      "  }\r",
                      "  else if( orientation[1] < 0 )\r",
                      "  {\r",
                      "    orientation[1] = 1;\r",
                      "    orientation[3] = -1 * orientation[3];\r",
                      "  }\r",
                      "  if( orientation[3] < 0 )\r",
                      "  {\r",
                      "    orientation[3] += 2*Math.PI;\r",
                      "  }\r",
                      "}\r",
                      ""
                    ],
                    "IS": {
                      "connect": [
                        {
                          "@nodeField": "id",
                          "@protoField": "id"
                        },
                        {
                          "@nodeField": "fieldOfView",
                          "@protoField": "fieldOfView"
                        },
                        {
                          "@nodeField": "orientation",
                          "@protoField": "orientation"
                        },
                        {
                          "@nodeField": "count",
                          "@protoField": "count"
                        }
                      ]
                    }
                  }
                },
                { "ROUTE":
                  {
                    "@fromNode": "PS",
                    "@fromField": "enterTime",
                    "@toNode": "S",
                    "@toField": "enter"
                  }
                },
                { "ROUTE":
                  {
                    "@fromNode": "PS",
                    "@fromField": "orientation_changed",
                    "@toNode": "S",
                    "@toField": "curOrientation"
                  }
                },
                { "ROUTE":
                  {
                    "@fromNode": "S",
                    "@fromField": "disable",
                    "@toNode": "PS",
                    "@toField": "set_enabled"
                  }
                }
              ]
            }
          }
        }
      ]
    }
